<?php
require_once 'includes/bootstrap.php';require_once 'includes/config.php';require_once 'includes/parent-auth.php';require_once 'includes/senior-school.php';require_once 'includes/portal-layout.php';
$parent=require_parent();$student=(int)($_GET['student']??0);$child=parent_child($dbh,$parent['id'],$student);$year=academic_year($dbh);
$placement=cbe_one($dbh,'SELECT p.Name Pathway,t.Name Track FROM tblstudentpathways a JOIN tblpathways p ON p.id=a.PathwayId LEFT JOIN tblpathwaytracks t ON t.id=a.TrackId WHERE a.StudentId=? AND a.AcademicYearId=? AND a.Status=1 ORDER BY a.id DESC LIMIT 1',[$student,$year]);
$classTeacher=academic_query($dbh,'SELECT u.FullName FROM tblclassteacherassignments a JOIN tblusers u ON u.id=a.TeacherId AND u.Status=1 WHERE a.ClassId=? AND a.AcademicYearId=? AND a.Status=1',[$child['ClassId'],$year])->fetchColumn();
portal_start('Learner academic profile');?><div class="report-actions"><a class="btn btn-default" href="parent-dashboard.php">My children</a> <a class="btn btn-primary" href="parent-report.php?student=<?= $student ?>">Published examinations</a> <a class="btn btn-default" href="parent-assessments.php?student=<?= $student ?>">Published assessments</a></div><section class="parent-card"><h2><?= academic_h($child['StudentName']) ?></h2><div class="report-meta"><?php foreach(['Admission number'=>$child['RollId'],'Grade'=>$child['GradeNumber'],'Class'=>$child['ClassName'].' '.$child['Section'],'Date of birth'=>$child['DOB']?:'Not recorded','Gender'=>$child['Gender']?:'Not recorded','Pathway'=>$placement['Pathway']??'Not allocated','Track'=>$placement['Track']??'Not allocated','Class teacher'=>$classTeacher?:'Not assigned','Academic year'=>academic_query($dbh,'SELECT AcademicYear FROM tblacademicyears WHERE id=?',[$year])->fetchColumn()?:'Not configured','Enrollment status'=>'Active','Guardian relationship'=>$child['Relationship']] as $label=>$value)echo '<p><strong>'.academic_h($label).':</strong> '.academic_h($value).'</p>';?></div><h3>Registered subjects</h3><div class="table-responsive"><table class="table"><thead><tr><th>Subject</th><th>Teacher</th></tr></thead><tbody><?php $subjects=cbe_rows($dbh,'SELECT s.SubjectName,(SELECT GROUP_CONCAT(DISTINCT u.FullName ORDER BY u.FullName SEPARATOR ", ") FROM tblsubjectteacherassignments a JOIN tblusers u ON u.id=a.TeacherId AND u.Status=1 WHERE a.ClassId=ss.ClassId AND a.SubjectId=ss.SubjectId AND a.AcademicYearId=ss.AcademicYearId AND a.Status=1 AND (a.TermId IS NULL OR EXISTS(SELECT 1 FROM tblterms t WHERE t.id=a.TermId AND t.IsActive=1))) Teacher FROM tblstudentsubjects ss JOIN tblsubjects s ON s.id=ss.SubjectId WHERE ss.StudentId=? AND ss.ClassId=? AND ss.AcademicYearId=? AND ss.Status=1 ORDER BY s.SubjectName',[$student,$child['ClassId'],$year]);foreach($subjects as $subject){?><tr><td><?= academic_h($subject['SubjectName']) ?></td><td><?= academic_h($subject['Teacher']??'Not assigned') ?></td></tr><?php }if(!$subjects)echo '<tr><td colspan="2">No subjects are registered for the active academic year.</td></tr>';?></tbody></table></div></section><?php portal_end(); ?>
